def solve(grid):
    n = len(grid)
    # find separator rows and columns (the grid lines)
    sep_rows = []
    for r in range(n):
        if all(grid[r][c] != 0 for c in range(n)):
            if len(set(grid[r])) == 1:
                sep_rows.append(r)
    sep_cols = []
    for c in range(n):
        if all(grid[r][c] != 0 for r in range(n)):
            if len(set(grid[r][c] for r in range(n))) == 1:
                sep_cols.append(c)

    # the colour of the grid lines
    G = grid[sep_rows[0]][sep_cols[0]]

    # the other non‑zero colour (the "object")
    O = None
    for r in range(n):
        for c in range(n):
            val = grid[r][c]
            if val != 0 and val != G:
                O = val
                break
        if O is not None:
            break

    # block starts
    row_blocks = []
    start = 0
    for sr in sep_rows:
        row_blocks.append(start)
        start = sr + 1
    row_blocks.append(start)   # last block start

    col_blocks = []
    start = 0
    for sc in sep_cols:
        col_blocks.append(start)
        start = sc + 1
    col_blocks.append(start)

    # union of object positions inside a block (relative coordinates)
    S = set()
    for br in range(3):
        for bc in range(3):
            r0 = row_blocks[br]
            c0 = col_blocks[bc]
            for r in range(5):
                for c in range(5):
                    if grid[r0 + r][c0 + c] == O:
                        S.add((r, c))

    # decide whether the centre has to be filled
    fill_centre = False
    for br in range(3):
        for bc in range(3):
            r0 = row_blocks[br]
            c0 = col_blocks[bc]
            ops = set()
            for r in range(5):
                for c in range(5):
                    if grid[r0 + r][c0 + c] == O:
                        ops.add((r, c))
            if (2, 2) not in ops and len(ops) >= 3:
                fill_centre = True
                break
        if fill_centre:
            break

    # make a copy of the original grid for the result
    out = [row[:] for row in grid]

    # apply the rule block by block
    for br in range(3):
        for bc in range(3):
            r0 = row_blocks[br]
            c0 = col_blocks[bc]
            for (r, c) in S:
                gr = r0 + r
                gc = c0 + c
                if grid[gr][gc] == O:
                    out[gr][gc] = O          # keep the object colour
                else:
                    out[gr][gc] = G          # otherwise put the grid colour

            # handle the centre separately
            if fill_centre:
                cr = r0 + 2
                cc = c0 + 2
                if grid[cr][cc] != O:
                    out[cr][cc] = G

    return out

